            if voicePinTurns.count > 3 {
                Button(showFullVoicePinThread ? "Recent 3" : "All \(voicePinTurns.count)") {
                    withAnimation(.easeInOut(duration: 0.18)) {
                        showFullVoicePinThread.toggle()
